    setEditForm({
      title: topic.title,
      angle: topic.angle,
      tags: [...topic.tags]
    });
  };

  const saveEdit = () => {
    if (editingTopic && editForm) {
      onEditTopic(editingTopic, editForm);
      setEditingTopic(null);
      setEditForm({});
    }
  };

  const cancelEdit = () => {
    setEditingTopic(null);
    setEditForm({});
  };

  return (
